class MainActivity: AppCompatActivity() {
 private val ex=Executors.newSingleThreadExecutor()
 private val handler=Handler(Looper.getMainLooper())
 private var autoRefresh: Runnable?=null
 private val locPerm=registerForActivityResult(ActivityResultContracts.RequestMultiplePermissions()){r->
  if(r[Manifest.permission.ACCESS_FINE_LOCATION]==true||r[Manifest.permission.ACCESS_COARSE_LOCATION]==true) startTracking() else toast("لازم تسمح بالموقع لتسجيل الحضور")
 }
 override fun onCreate(b:Bundle?){super.onCreate(b); val role=SessionStore.role(this); if(SessionStore.token(this)!=null) showDashboard(role?:"employee",SessionStore.email(this)) else showLogin()}
 override fun onDestroy(){super.onDestroy(); autoRefresh?.let{handler.removeCallbacks(it)}; ex.shutdownNow()}
 private fun box():LinearLayout=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(24,24,24,24);layoutDirection=View.LAYOUT_DIRECTION_RTL}
 private fun txt(s:String,size:Float=16f)=TextView(this).apply{text=s;textSize=size;setPadding(8,10,8,10)}
 private fun field(h:String,secret:Boolean=false)=EditText(this).apply{hint=h;setPadding(14,12,14,12);if(secret)inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD}
 private fun toast(s:String){runOnUiThread{Toast.makeText(this,s,Toast.LENGTH_LONG).show()}}
 private fun showLogin(){val root=box();root.addView(txt("مرحبا بك يا زياد 👋",28f));root.addView(txt("Fawry Employee Manager",18f));if(!SupabaseConfig.configured())root.addView(txt("وضع التجربة مفعل — بيانات Supabase لم تُضف بعد",14f));val email=field("البريد الإلكتروني");val pass=field("كلمة المرور",true);val btn=Button(this).apply{text="دخول"};root.addView(email);root.addView(pass);root.addView(btn);setContentView(root);btn.setOnClickListener{val e=email.text.toString().trim();val p=pass.text.toString();if(e.isBlank()||p.isBlank()){toast("اكتب البريد وكلمة المرور");return@setOnClickListener};btn.isEnabled=false;ex.execute{SupabaseApi.login(e,p).onSuccess{s->SupabaseApi.getProfile(s.accessToken,s.userId).onSuccess{pf->val role=pf?.optString("role","employee")?:"employee";SessionStore.save(this,s,role,pf?.optString("employee_id"));runOnUiThread{showDashboard(role,e)}}.onFailure{toast(it.message?:"تعذر قراءة الحساب")}}.onFailure{toast(it.message?:"فشل تسجيل الدخول")};runOnUiThread{btn.isEnabled=true}}}}
 private fun showDashboard(role:String,email:String){if(role=="manager"||role=="admin")showManager(email) else showEmployee(email)}
 private fun showEmployee(email:String){val root=box();root.addView(txt("مرحبا بك 👋",26f));root.addView(txt("$email\nحساب موظف",16f));val inb=Button(this).apply{text="📍 حضور وبدء تتبع الموقع"};val out=Button(this).apply{text="⏹️ انصراف وتسجيل الإنتاج"};val req=Button(this).apply{text="📝 طلباتي"};val report=Button(this).apply{text="📊 تقريري الشهري"};val notif=Button(this).apply{text="🔔 الإشعارات"};val pwd=Button(this).apply{text="🔐 تغيير كلمة المرور"};val logout=Button(this).apply{text="تسجيل خروج"};listOf(inb,out,req,report,notif,pwd,logout).forEach{root.addView(it)};setContentView(root);inb.setOnClickListener{ensureLocationThenStart()};out.setOnClickListener{showCheckout()};req.setOnClickListener{showEmployeeRequests()};report.setOnClickListener{showEmployeeReport()};notif.setOnClickListener{showNotifications{showEmployee(email)}};pwd.setOnClickListener{showChangePassword{showEmployee(email)}};logout.setOnClickListener{stopTracking();SessionStore.clear(this);showLogin()}}
 private fun showCheckout(){val root=box();root.addView(txt("تسجيل الانصراف",25f));val cards=field("Cards اليوم");cards.inputType=2;val fawry=field("Fawry Yawmy اليوم");fawry.inputType=2;val save=Button(this).apply{text="حفظ الانصراف"};val cancel=Button(this).apply{text="رجوع"};root.addView(cards);root.addView(fawry);root.addView(save);root.addView(cancel);setContentView(root);save.setOnClickListener{val c=cards.text.toString().toIntOrNull();val f=fawry.text.toString().toIntOrNull();if(c==null||f==null||c<0||f<0){toast("اكتب أرقام صحيحة");return@setOnClickListener};val eid=SessionStore.employeeId(this);val token=SessionStore.token(this);if(eid==null||token==null){toast("الحساب غير مربوط بموظف");return@setOnClickListener};save.isEnabled=false;ex.execute{SupabaseApi.checkout(token,eid,c,f).onSuccess{stopTracking();toast("تم الحفظ بنجاح وتم تحديث التقرير الشهري ولوحة المدير");runOnUiThread{showEmployee(SessionStore.email(this))}}.onFailure{toast(it.message?:"تعذر الحفظ");runOnUiThread{save.isEnabled=true}}}};cancel.setOnClickListener{showEmployee(SessionStore.email(this))}}
 private fun showEmployeeRequests(){val root=box();root.addView(txt("📝 طلباتي",25f));val type=Spinner(this).apply{adapter=ArrayAdapter(this@MainActivity,android.R.layout.simple_spinner_dropdown_item,listOf("إجازة","مأمورية","إذن","مشكلة","أخرى"))};val msg=field("تفاصيل الطلب");val send=Button(this).apply{text="إرسال الطلب"};val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(type);root.addView(msg);root.addView(send);root.addView(txt("سجل الطلبات",20f));root.addView(ScrollView(this).apply{addView(list)},LinearLayout.LayoutParams(-1,0,1f));val back=Button(this).apply{text="رجوع"};root.addView(back);setContentView(root);fun load(){val t=SessionStore.token(this)?:return;val e=SessionStore.employeeId(this)?:return;ex.execute{SupabaseApi.requests(t,e).onSuccess{rows->runOnUiThread{list.removeAllViews();rows.forEach{list.addView(txt("${it.type} • ${it.status}\n${it.message?:""}\n${it.managerNote?.let{"ملاحظة المدير: $it"}?:""}\n${it.createdAt}",15f))}}}.onFailure{toast(it.message?:"تعذر تحميل الطلبات")}}};send.setOnClickListener{val t=SessionStore.token(this)?:return@setOnClickListener;val e=SessionStore.employeeId(this)?:return@setOnClickListener;send.isEnabled=false;ex.execute{SupabaseApi.createRequest(t,e,type.selectedItem.toString(),msg.text.toString()).onSuccess{toast("تم إرسال الطلب للمدير");runOnUiThread{msg.text.clear();send.isEnabled=true;load()}}.onFailure{toast(it.message?:"تعذر إرسال الطلب");runOnUiThread{send.isEnabled=true}}}};back.setOnClickListener{showEmployee(SessionStore.email(this))};load()}
 private fun showEmployeeReport(){val root=box();root.addView(txt("📊 تقريري الشهري",25f));val summary=txt("جارٍ تحميل التقرير...",16f);root.addView(summary);val table=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(ScrollView(this).apply{addView(table)},LinearLayout.LayoutParams(-1,0,1f));val back=Button(this).apply{text="رجوع"};root.addView(back);setContentView(root);back.setOnClickListener{showEmployee(SessionStore.email(this))};val t=SessionStore.token(this)?:return;val e=SessionStore.employeeId(this)?:return;ex.execute{val m=SupabaseApi.monthlyPerformance(t,e);val a=SupabaseApi.employeeAttendance(t,e);runOnUiThread{val rows=m.getOrElse{emptyList()};val totalC=rows.sumOf{it.cards};val totalF=rows.sumOf{it.fawry};summary.text="إجمالي Cards: $totalC | إجمالي Fawry Yawmy: $totalF\nالهدف الشهري: 200 لكل منتج\nأيام الحضور المسجلة: ${a.getOrElse{emptyList()}.count{it.checkIn!=null}}";table.addView(txt("الشهر | Cards | Fawry | Cards% | Fawry%",15f));rows.forEach{r->table.addView(txt("${r.month}/${r.year} | ${r.cards} | ${r.fawry} | ${r.cards*100/200}% | ${r.fawry*100/200}%",15f))}}}}
 private fun showManager(email:String){autoRefresh?.let{handler.removeCallbacks(it)};val root=box();root.addView(txt("📊 لوحة المدير",28f));root.addView(txt("$email\nمتابعة الموظفين والأداء",16f));val stats=txt("جارٍ التحميل...",17f);root.addView(stats);val add=Button(this).apply{text="➕ إضافة موظف وحساب دخول"};val requests=Button(this).apply{text="📝 طلبات الموظفين"};val notif=Button(this).apply{text="🔔 الإشعارات"};val map=Button(this).apply{text="🗺️ خريطة المواقع ومسار الحركة"};val pwd=Button(this).apply{text="🔐 تغيير كلمة مرور المدير"};val refresh=Button(this).apply{text="🔄 تحديث البيانات"};listOf(add,requests,notif,map,pwd,refresh).forEach{root.addView(it)};val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(ScrollView(this).apply{addView(list)},LinearLayout.LayoutParams(-1,0,1f));val logout=Button(this).apply{text="تسجيل خروج"};root.addView(logout);setContentView(root);fun load(){val t=SessionStore.token(this)?:return;ex.execute{val er=SupabaseApi.employees(t);val ar=SupabaseApi.todayAttendance(t);val nr=SupabaseApi.unreadNotifications(t);runOnUiThread{if(er.isFailure){toast(er.exceptionOrNull()?.message?:"تعذر تحميل الموظفين");return@runOnUiThread};val emps=er.getOrThrow();val att=ar.getOrElse{emptyList()};val by=att.associateBy{it.employeeId};val active=emps.count{it.active};val present=emps.count{it.active&&by[it.id]?.checkIn!=null};val done=emps.count{by[it.id]?.checkOut!=null};stats.text="👥 ${emps.size} | 🟢 نشط ${active} | 📍 حاضر $present | ⏹️ منصرف $done\n💳 Cards ${att.sumOf{it.cards}} | 💰 Fawry ${att.sumOf{it.fawry}} | 🔔 إشعارات غير مقروءة ${nr.getOrElse{emptyList()}.size}";list.removeAllViews();emps.forEach{e->val a=by[e.id];val status=when{!e.active->"غير نشط";a?.checkOut!=null->"منصرف";a?.checkIn!=null->"حاضر";else->"لم يسجل"};list.addView(Button(this).apply{text="${e.name}\n${e.code?:"-"} • ${e.location?:"-"}\n$status | Cards ${a?.cards?:0} | Fawry ${a?.fawry?:0}";setOnClickListener{showEmployeeDetails(e)}})}}}};add.setOnClickListener{showAddEmployee{showManager(email)}};requests.setOnClickListener{showManagerRequests{showManager(email)}};notif.setOnClickListener{showNotifications{showManager(email)}};map.setOnClickListener{showManagerMap()};pwd.setOnClickListener{showChangePassword{showManager(email)}};refresh.setOnClickListener{load()};logout.setOnClickListener{SessionStore.clear(this);showLogin()};load();autoRefresh=object:Runnable{override fun run(){load();handler.postDelayed(this,15000)}};handler.postDelayed(autoRefresh!!,15000)}
 private fun showManagerRequests(done:()->Unit){val root=box();root.addView(txt("📝 طلبات الموظفين",25f));val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(ScrollView(this).apply{addView(list)},LinearLayout.LayoutParams(-1,0,1f));val back=Button(this).apply{text="رجوع"};root.addView(back);setContentView(root);fun load(){val t=SessionStore.token(this)?:return;ex.execute{SupabaseApi.allRequests(t).onSuccess{rows->runOnUiThread{list.removeAllViews();rows.forEach{r->val b=Button(this).apply{text="${r.employeeName} • ${r.type}\n${r.status}\n${r.message?:""}\n${r.createdAt}";setOnClickListener{reviewRequest(r,done)}};list.addView(b)}}}.onFailure{toast(it.message?:"تعذر تحميل الطلبات")}}};back.setOnClickListener(done);load()}
 private fun reviewRequest(r:RequestRow,done:()->Unit){val root=box();root.addView(txt("مراجعة الطلب",24f));root.addView(txt("${r.employeeName}\nالنوع: ${r.type}\n${r.message?:""}",16f));val note=field("ملاحظة المدير");val approve=Button(this).apply{text="✅ موافقة"};val reject=Button(this).apply{text="❌ رفض"};val back=Button(this).apply{text="رجوع"};listOf(note,approve,reject,back).forEach{root.addView(it)};setContentView(root);fun update(s:String){val t=SessionStore.token(this)?:return;approve.isEnabled=false;reject.isEnabled=false;ex.execute{SupabaseApi.reviewRequest(t,r.id,s,note.text.toString()).onSuccess{toast("تم تحديث الطلب");runOnUiThread{done()}}.onFailure{toast(it.message?:"تعذر تحديث الطلب");runOnUiThread{approve.isEnabled=true;reject.isEnabled=true}}}};approve.setOnClickListener{update("approved")};reject.setOnClickListener{update("rejected")};back.setOnClickListener(done)}
 private fun showNotifications(done:()->Unit){val root=box();root.addView(txt("🔔 الإشعارات",25f));val list=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(ScrollView(this).apply{addView(list)},LinearLayout.LayoutParams(-1,0,1f));val read=Button(this).apply{text="تحديد الكل كمقروء"};val back=Button(this).apply{text="رجوع"};root.addView(read);root.addView(back);setContentView(root);val t=SessionStore.token(this)?:return;fun load(){ex.execute{SupabaseApi.notifications(t).onSuccess{rows->runOnUiThread{list.removeAllViews();rows.forEach{list.addView(txt("${if(it.isRead)"" else "🟠 "}${it.title}\n${it.body}\n${it.createdAt}",15f))}}}.onFailure{toast(it.message?:"تعذر تحميل الإشعارات")}}};read.setOnClickListener{ex.execute{SupabaseApi.markNotificationsRead(t).onSuccess{runOnUiThread{load()}}}};back.setOnClickListener(done);load()}
 private fun showEmployeeDetails(e:Employee){val root=box();root.addView(txt("ملف الموظف",25f));root.addView(txt("${e.name}\nالكود: ${e.code?:"-"}\nالمكان: ${e.location?:"-"}\nالحساب: ${e.email?:"-"}",16f));val summary=txt("جارٍ تحميل التقرير...",16f);root.addView(summary);val table=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};root.addView(ScrollView(this).apply{addView(table)},LinearLayout.LayoutParams(-1,0,1f));val back=Button(this).apply{text="رجوع"};root.addView(back);setContentView(root);back.setOnClickListener{showManager(SessionStore.email(this))};val t=SessionStore.token(this)?:return;ex.execute{val m=SupabaseApi.monthlyPerformance(t,e.id);val a=SupabaseApi.employeeAttendance(t,e.id);val l=SupabaseApi.employeeLocations(t,e.id);runOnUiThread{val rows=m.getOrElse{emptyList()};val at=a.getOrElse{emptyList()};summary.text="إجمالي Cards: ${rows.sumOf{it.cards}} | إجمالي Fawry: ${rows.sumOf{it.fawry}}\nأيام الحضور: ${at.count{it.checkIn!=null}} | نقاط GPS: ${l.getOrElse{emptyList()}.size}";table.addView(txt("الشهر | Cards | Fawry | Cards% | Fawry%",15f));rows.forEach{r->table.addView(txt("${r.month}/${r.year} | ${r.cards} | ${r.fawry} | ${r.cards*100/200}% | ${r.fawry*100/200}%",15f))}}}}
 private fun showManagerMap(){val root=box();root.addView(txt("🗺️ مواقع الموظفين",24f));val info=txt("جارٍ تحميل آخر المواقع...",15f);root.addView(info);val web=WebView(this).apply{settings.javaScriptEnabled=true;settings.domStorageEnabled=true;webViewClient=WebViewClient()};root.addView(web,LinearLayout.LayoutParams(-1,0,1f));val back=Button(this).apply{text="رجوع"};root.addView(back);setContentView(root);back.setOnClickListener{showManager(SessionStore.email(this))};val t=SessionStore.token(this)?:return;ex.execute{SupabaseApi.latestLocations(t).onSuccess{rows->val latest=rows.distinctBy{it.employeeId};val points=latest.joinToString(","){"[${it.lat},${it.lng}]"};runOnUiThread{info.text="آخر نقاط: ${latest.size}";web.loadDataWithBaseURL(null,mapHtml(points),"text/html","UTF-8",null)}}.onFailure{toast(it.message?:"تعذر تحميل المواقع")}}}
 private fun mapHtml(points:String)= """<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>html,body,#m{height:100%;margin:0}</style><link rel='stylesheet' href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css'><script src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'></script></head><body><div id='m'></div><script>const p=[$points];const m=L.map('m').setView(p[0]||[31.26,32.30],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(m);p.forEach(x=>L.marker(x).addTo(m));</script></body></html>"""
 private fun showChangePassword(done:()->Unit){val root=box();root.addView(txt("🔐 تغيير كلمة المرور",25f));val p1=field("كلمة المرور الجديدة",true);val p2=field("تأكيد كلمة المرور",true);val save=Button(this).apply{text="حفظ"};val back=Button(this).apply{text="رجوع"};listOf(p1,p2,save,back).forEach{root.addView(it)};setContentView(root);save.setOnClickListener{val a=p1.text.toString();val b=p2.text.toString();if(a.length<8){toast("8 أحرف على الأقل");return@setOnClickListener};if(a!=b){toast("التأكيد غير مطابق");return@setOnClickListener};val t=SessionStore.token(this)?:return@setOnClickListener;ex.execute{SupabaseApi.changePassword(t,a).onSuccess{toast("تم تغيير كلمة المرور بنجاح");runOnUiThread{done()}}.onFailure{toast(it.message?:"تعذر تغيير كلمة المرور")}}};back.setOnClickListener(done)}
 private fun showAddEmployee(done:()->Unit){val root=box();root.addView(txt("➕ إضافة موظف",25f));val fields=listOf(field("اسم الموظف"),field("البريد الإلكتروني"),field("كلمة المرور",true),field("كود الموظف"),field("تاريخ التعيين YYYY-MM-DD"),field("مكان العمل"),field("Limit الإيصالات"),field("POS Limit"),field("ملاحظات"));fields.forEach{root.addView(it)};val save=Button(this).apply{text="إنشاء الموظف والحساب"};val back=Button(this).apply{text="رجوع"};root.addView(save);root.addView(back);setContentView(root);save.setOnClickListener{if(fields.take(4).any{it.text.isBlank()}){toast("الاسم والبريد والباسورد والكود مطلوبين");return@setOnClickListener};val t=SessionStore.token(this)?:return@setOnClickListener;ex.execute{SupabaseApi.createEmployeeUser(t,fields[0].text.toString(),fields[1].text.toString(),fields[2].text.toString(),fields[3].text.toString(),fields[4].text.toString(),fields[5].text.toString(),fields[6].text.toString(),fields[7].text.toString(),fields[8].text.toString()).onSuccess{toast("تم إنشاء الموظف وحساب الدخول");runOnUiThread{done()}}.onFailure{toast(it.message?:"فشل إنشاء الموظف")}}};back.setOnClickListener(done)}
 private fun ensureLocationThenStart(){val ok=ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;if(ok)startTracking()else locPerm.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION))}
 private fun startTracking(){val i=Intent(this,LocationService::class.java).putExtra("employeeId",SessionStore.employeeId(this));ContextCompat.startForegroundService(this,i);toast("تم تسجيل الحضور وبدأ تتبع الموقع")}
 private fun stopTracking(){stopService(Intent(this,LocationService::class.java))}
}

data class Session(val accessToken:String,val userId:String,val email:String)
data class Employee(val id:String,val name:String,val code:String?,val email:String?,val location:String?,val active:Boolean)
data class AttendanceRow(val employeeId:String,val date:String,val checkIn:String?,val checkOut:String?,val cards:Int,val fawry:Int)
data class LocationRow(val employeeId:String,val lat:Double,val lng:Double,val accuracy:Double,val capturedAt:String)
data class MonthlyRow(val year:Int,val month:Int,val cards:Int,val fawry:Int)
data class RequestRow(val id:String,val employeeId:String,val employeeName:String,val type:String,val message:String?,val status:String,val managerNote:String?,val createdAt:String)
data class NotificationRow(val id:String,val title:String,val body:String,val kind:String,val isRead:Boolean,val createdAt:String)

object SupabaseApi{
 fun changePassword(t:String,p:String)=runCatching{if(p.length<8)error("كلمة المرور قصيرة");val r=req("/auth/v1/user","PATCH",JSONObject().put("password",p).toString(),t);if(r.c !in 200..299)error("تعذر تغيير كلمة المرور (${r.c})");Unit}
 fun login(e:String,p:String)=runCatching{if(!SupabaseConfig.configured()){when{"admin@demo.local"==e && "admin123"==p->Session("DEMO_TOKEN","demo-admin",e);"employee@demo.local"==e && "employee123"==p->Session("DEMO_TOKEN","demo-employee-user",e);else->error("حساب التجربة: admin@demo.local / admin123 أو employee@demo.local / employee123")}}else{val r=req("/auth/v1/token?grant_type=password","POST",JSONObject().put("email",e).put("password",p).toString(),null);if(r.c !in 200..299)error("تسجيل الدخول فشل (${r.c})");Unit;val j=JSONObject(r.b);Session(j.getString("access_token"),j.getJSONObject("user").getString("id"),j.getJSONObject("user").optString("email",e))}}
 fun getProfile(t:String,u:String)=runCatching{if(t=="DEMO_TOKEN"){JSONObject().put("role",if(u=="demo-admin")"admin" else "employee").put("employee_id",if(u=="demo-admin")JSONObject.NULL else "demo-1")}else{val r=req("/rest/v1/profiles?select=*&id=eq.$u","GET",null,t);if(r.c !in 200..299)error("تعذر قراءة الحساب");Unit;val a=JSONArray(r.b);if(a.length()==0)null else a.getJSONObject(0)}}
 fun employees(t:String)=runCatching{if(t=="DEMO_TOKEN") demoEmployees() else {val a=arr(req("/rest/v1/employees?select=*&order=full_name.asc","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(Employee(j.getString("id"),j.getString("full_name"),j.optString("employee_code").ifBlank{null},j.optString("email").ifBlank{null},j.optString("work_location").ifBlank{null},j.optBoolean("active",true)))}}}}
 fun todayAttendance(t:String)=runCatching{if(t=="DEMO_TOKEN") demoAttendance() else {val d=LocalDate.now();val a=arr(req("/rest/v1/attendance?select=employee_id,work_date,check_in,check_out,cards,fawry_yawmy&work_date=eq.$d","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(AttendanceRow(j.getString("employee_id"),j.getString("work_date"),j.optString("check_in").ifBlank{null},j.optString("check_out").ifBlank{null},j.optInt("cards"),j.optInt("fawry_yawmy")))}}}}
 fun employeeAttendance(t:String,e:String)=runCatching{if(t=="DEMO_TOKEN") demoAttendance().filter{it.employeeId==e} else {val a=arr(req("/rest/v1/attendance?employee_id=eq.$e&select=employee_id,work_date,check_in,check_out,cards,fawry_yawmy&order=work_date.desc","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(AttendanceRow(j.getString("employee_id"),j.getString("work_date"),j.optString("check_in").ifBlank{null},j.optString("check_out").ifBlank{null},j.optInt("cards"),j.optInt("fawry_yawmy")))}}}}
 fun createAttendance(t:String,e:String,lat:Double?,lng:Double?):Result<String> = runCatching{if(t=="DEMO_TOKEN") "demo-attendance-${e}-${LocalDate.now()}" else {val date=LocalDate.now().toString();val j=JSONObject().put("employee_id",e).put("work_date",date).put("check_in",java.time.Instant.now().toString());if(lat!=null)j.put("check_in_lat",lat);if(lng!=null)j.put("check_in_lng",lng);val r=req("/rest/v1/attendance?on_conflict=employee_id,work_date","POST",j.toString(),t);if(r.c !in 200..299)error("تعذر تسجيل الحضور (${r.c})");Unit;val a=JSONArray(r.b);if(a.length()==0) error("لم يرجع الخادم رقم الحضور");a.getJSONObject(0).getString("id")}}
 fun addLocation(t:String,e:String,aid:String?,lat:Double,lng:Double,accuracy:Float):Result<Unit> = runCatching{if(t=="DEMO_TOKEN") Unit else {val j=JSONObject().put("employee_id",e).put("latitude",lat).put("longitude",lng).put("accuracy_m",accuracy);if(aid!=null)j.put("attendance_id",aid);val r=req("/rest/v1/location_samples","POST",j.toString(),t);if(r.c !in 200..299)error("تعذر رفع الموقع (${r.c})");Unit}}
 fun checkout(t:String,e:String,c:Int,f:Int)=runCatching{if(t=="DEMO_TOKEN") Unit else {val d=LocalDate.now();val j=JSONObject().put("check_out",java.time.Instant.now().toString()).put("cards",c).put("fawry_yawmy",f);val r=req("/rest/v1/attendance?employee_id=eq.$e&work_date=eq.$d","PATCH",j.toString(),t);if(r.c !in 200..299)error("تعذر الحفظ (${r.c})");Unit}}
 fun monthlyPerformance(t:String,e:String)=runCatching{if(t=="DEMO_TOKEN") demoMonthly(e) else {val a=arr(req("/rest/v1/monthly_performance?employee_id=eq.$e&select=year,month,cards,fawry_yawmy&order=year.asc,month.asc","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(MonthlyRow(j.getInt("year"),j.getInt("month"),j.optInt("cards"),j.optInt("fawry_yawmy")))}}}}
 fun createRequest(t:String,e:String,type:String,msg:String)=runCatching{if(t=="DEMO_TOKEN"){demoRequests.add(RequestRow("demo-req-${System.currentTimeMillis()}",e,"أحمد موظف","$type",msg,"pending",null,java.time.Instant.now().toString()));demoNotifications.add(NotificationRow("demo-notif-${System.currentTimeMillis()}","طلب موظف جديد","تم إرسال طلب تجريبي","request",false,java.time.Instant.now().toString()))}else{val r=req("/rest/v1/requests","POST",JSONObject().put("employee_id",e).put("type",type).put("message",msg).toString(),t);if(r.c !in 200..299)error("تعذر إرسال الطلب (${r.c})");Unit}}
 fun requests(t:String,e:String)=runCatching{if(t=="DEMO_TOKEN") demoRequests.filter{it.employeeId==e} else {val a=arr(req("/rest/v1/requests?employee_id=eq.$e&select=*&order=created_at.desc","GET",null,t));parseRequests(a)}}
 fun allRequests(t:String)=runCatching{if(t=="DEMO_TOKEN") demoRequests else {val a=arr(req("/rest/v1/requests?select=*,employees(full_name)&order=created_at.desc","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(RequestRow(j.getString("id"),j.getString("employee_id"),j.optJSONObject("employees")?.optString("full_name")?:"موظف",j.getString("type"),j.optString("message").ifBlank{null},j.getString("status"),j.optString("manager_note").ifBlank{null},j.getString("created_at")))}}}}
 fun reviewRequest(t:String,id:String,status:String,note:String)=runCatching{if(t=="DEMO_TOKEN"){val i=demoRequests.indexOfFirst{it.id==id};if(i>=0){val old=demoRequests[i];demoRequests[i]=old.copy(status=status,managerNote=note);demoNotifications.add(NotificationRow("demo-review-${System.currentTimeMillis()}","تحديث طلبك","تم $status الطلب التجريبي","request_review",false,java.time.Instant.now().toString()))}}else{val r=req("/rest/v1/requests?id=eq.$id","PATCH",JSONObject().put("status",status).put("manager_note",note).put("reviewed_at",java.time.Instant.now().toString()).toString(),t);if(r.c !in 200..299)error("تعذر تحديث الطلب (${r.c})");Unit}}
 fun notifications(t:String)=runCatching{if(t=="DEMO_TOKEN") demoNotifications else {val a=arr(req("/rest/v1/notifications?select=*&order=created_at.desc&limit=100","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(NotificationRow(j.getString("id"),j.getString("title"),j.getString("body"),j.getString("kind"),j.optBoolean("is_read"),j.getString("created_at")))}}}}
 fun unreadNotifications(t:String)=runCatching{if(t=="DEMO_TOKEN") demoNotifications.filter{!it.isRead}.map{it.id} else {val a=arr(req("/rest/v1/notifications?select=id&is_read=eq.false&limit=100","GET",null,t));buildList{for(i in 0 until a.length())add(a.getJSONObject(i).getString("id"))}}}
 fun markNotificationsRead(t:String)=runCatching{if(t=="DEMO_TOKEN"){demoNotifications=demoNotifications.map{it.copy(isRead=true)}.toMutableList()}else{val r=req("/rest/v1/notifications?is_read=eq.false","PATCH",JSONObject().put("is_read",true).toString(),t);if(r.c !in 200..299)error("تعذر تحديث الإشعارات");Unit}}
 fun latestLocations(t:String)=runCatching{if(t=="DEMO_TOKEN") demoLocations else {val a=arr(req("/rest/v1/location_samples?select=employee_id,latitude,longitude,accuracy_m,captured_at&order=captured_at.desc&limit=1000","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(LocationRow(j.getString("employee_id"),j.getDouble("latitude"),j.getDouble("longitude"),j.optDouble("accuracy_m",0.0),j.getString("captured_at")))}}}}
 fun employeeLocations(t:String,e:String)=runCatching{if(t=="DEMO_TOKEN") demoLocations.filter{it.employeeId==e} else {val a=arr(req("/rest/v1/location_samples?employee_id=eq.$e&select=employee_id,latitude,longitude,accuracy_m,captured_at&order=captured_at.asc&limit=1000","GET",null,t));buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(LocationRow(j.getString("employee_id"),j.getDouble("latitude"),j.getDouble("longitude"),j.optDouble("accuracy_m",0.0),j.getString("captured_at")))}}}}
 fun createEmployeeUser(t:String,name:String,email:String,pwd:String,code:String,hire:String,loc:String,rec:String,pos:String,notes:String)=runCatching{if(t=="DEMO_TOKEN"){demoEmployeesMutable.add(Employee("demo-${demoEmployeesMutable.size+1}",name,code,email,loc,true))}else{val j=JSONObject().put("full_name",name).put("email",email).put("password",pwd).put("employee_code",code);if(hire.isNotBlank())j.put("hire_date",hire);if(loc.isNotBlank())j.put("work_location",loc);if(rec.isNotBlank())j.put("receipt_limit",rec.toDouble());if(pos.isNotBlank())j.put("pos_limit",pos.toDouble());if(notes.isNotBlank())j.put("notes",notes);val r=req("/functions/v1/create-employee-user","POST",j.toString(),t);if(r.c !in 200..299)error("إنشاء الحساب فشل (${r.c})");Unit}}
 private val demoEmployeesMutable=mutableListOf(Employee("demo-1","أحمد محمد","EMP001","employee@demo.local","PortsaidComm",true),Employee("demo-2","محمد علي","EMP002","mohamed@demo.local","PortsaidUni",true),Employee("demo-3","سارة حسن","EMP003","sara@demo.local","PortsaidSci",true),Employee("demo-4","يوسف خالد","EMP004","youssef@demo.local","Hourasuni",true))
 private var demoRequests=mutableListOf(RequestRow("demo-req-1","demo-1","أحمد محمد","إذن","إذن لمدة ساعتين","pending",null,java.time.Instant.now().toString()))
 private var demoNotifications=mutableListOf(NotificationRow("demo-n1","طلب موظف جديد","تم إرسال طلب تجريبي من أحمد محمد","request",false,java.time.Instant.now().toString()))
 private val demoLocations=listOf(LocationRow("demo-1",31.265,32.301,12.0,java.time.Instant.now().toString()),LocationRow("demo-2",31.260,32.295,18.0,java.time.Instant.now().toString()))
 private fun demoEmployees()=demoEmployeesMutable.toList()
 private fun demoAttendance()=listOf(AttendanceRow("demo-1",LocalDate.now().toString(),"08:10",null,165,182),AttendanceRow("demo-2",LocalDate.now().toString(),"08:25","16:20",210,198),AttendanceRow("demo-3",LocalDate.now().toString(),"09:00",null,120,145))
 private fun demoMonthly(e:String)=listOf(MonthlyRow(2026,7,180,195),MonthlyRow(2026,8,205,220),MonthlyRow(2026,9,165,190))
 private fun parseRequests(a:JSONArray)=buildList{for(i in 0 until a.length()){val j=a.getJSONObject(i);add(RequestRow(j.getString("id"),j.getString("employee_id"),"أنت",j.getString("type"),j.optString("message").ifBlank{null},j.getString("status"),j.optString("manager_note").ifBlank{null},j.getString("created_at")))}}
 private fun arr(r:Resp)=JSONArray(r.b)
 private data class Resp(val c:Int,val b:String)
 private fun req(path:String,method:String,body:String?,token:String?):Resp{if(!SupabaseConfig.configured()) error("وضع التجربة: استخدم حسابات التجربة أو أضف إعدادات Supabase");val c=URL(SupabaseConfig.URL.trimEnd('/')+path).openConnection() as HttpURLConnection;c.requestMethod=method;c.setRequestProperty("apikey",SupabaseConfig.ANON_KEY);c.setRequestProperty("Content-Type","application/json");if(token!=null)c.setRequestProperty("Authorization","Bearer $token");if(body!=null){c.doOutput=true;c.outputStream.use{it.write(body.toByteArray())}};val code=c.responseCode;val s=if(code>=400)c.errorStream else c.inputStream;val b=s?.bufferedReader()?.use{it.readText()}?:"";c.disconnect();return Resp(code,b)}
}
object SessionStore{private const val P="session";fun save(c:Context,s:Session,r:String,e:String?){c.getSharedPreferences(P,0).edit().putString("token",s.accessToken).putString("userId",s.userId).putString("email",s.email).putString("role",r).putString("employeeId",e).apply()};fun clear(c:Context)=c.getSharedPreferences(P,0).edit().clear().apply();fun token(c:Context)=c.getSharedPreferences(P,0).getString("token",null);fun role(c:Context)=c.getSharedPreferences(P,0).getString("role",null);fun employeeId(c:Context)=c.getSharedPreferences(P,0).getString("employeeId",null);fun email(c:Context)=c.getSharedPreferences(P,0).getString("email","")?:""}
